import 'dart:convert';import 'package:flutter_dotenv/flutter_dotenv.dart';import 'package:geolocator/geolocator.dart';import 'package:http/http.dart' as http;import '../models/weather_model.dart';class WeatherService {  static const String _baseUrl = 'https://api.openweathermap.org/data/2.5';  String get _apiKey => dotenv.env['OPENWEATHER_API_KEY'] ?? '';  /// Gets the device's current location. Requests permission if needed.  Future<Position> _getCurrentLocation() async {    bool serviceEnabled = await Geolocator.isLocationServiceEnabled();    if (!serviceEnabled) {      throw Exception('Location services are disabled.');    }    LocationPermission permission = await Geolocator.checkPermission();    if (permission == LocationPermission.denied) {      permission = await Geolocator.requestPermission();      if (permission == LocationPermission.denied) {        throw Exception('Location permission denied.');      }    }    if (permission == LocationPermission.deniedForever) {      throw Exception('Location permission permanently denied.');    }    return await Geolocator.getCurrentPosition(      desiredAccuracy: LocationAccuracy.medium,    );  }  /// Fetches current weather + 5-day forecast, and calculates disease risk.  Future<WeatherModel> fetchWeatherAndRisk() async {    if (_apiKey.isEmpty) {      throw Exception('OPENWEATHER_API_KEY not found. Check your .env file.');    }    final position = await _getCurrentLocation();    // Current weather    final currentUrl = Uri.parse(      '$_baseUrl/weather?lat=${position.latitude}&lon=${position.longitude}&appid=$_apiKey&units=metric',    );    final currentResponse = await http.get(currentUrl);    if (currentResponse.statusCode != 200) {      throw Exception('Weather fetch failed: ${currentResponse.statusCode}');    }    final currentData = jsonDecode(currentResponse.body);    // 5-day / 3-hour forecast    final forecastUrl = Uri.parse(      '$_baseUrl/forecast?lat=${position.latitude}&lon=${position.longitude}&appid=$_apiKey&units=metric',    );    final forecastResponse = await http.get(forecastUrl);    if (forecastResponse.statusCode != 200) {      throw Exception('Forecast fetch failed: ${forecastResponse.statusCode}');    }    final forecastData = jsonDecode(forecastResponse.body);    return WeatherModel.fromApiData(currentData, forecastData);  }}